import { useState, useEffect } from 'react';
import axios from 'axios';

function Vendas() {
  const [titulo, setTitulo] = useState('');
  const [descricao, setDescricao] = useState('');
  const [preco, setPreco] = useState('');
  const [produtos, setProdutos] = useState([]);
  const [categoria, setCategoria] = useState('');

  const carregarProdutos = async () => {
    try {
      const response = await axios.get('/vendas');
      setProdutos(response.data);
    } catch (error) {
      console.error('Erro ao carregar produtos', error);
    }
  };

  useEffect(() => {
    carregarProdutos();
  }, []);

  const cadastrarProduto = async (e) => {
    e.preventDefault();
    try {
      const token = localStorage.getItem('token');
      await axios.post('/vendas', { titulo, descricao, preco }, {
        headers: { Authorization: `Bearer ${token}` }
      });
      alert('Produto cadastrado com sucesso!');
      setTitulo('');
      setDescricao('');
      setPreco('');
      carregarProdutos();
    } catch (error) {
      alert('Erro ao cadastrar produto');
    }
  };

  return (
    <div className="p-8">
      <h2 className="text-2xl font-bold text-green-600 mb-4">Página de Vendas</h2>
      <form onSubmit={cadastrarProduto} className="flex flex-col gap-4 mb-6">
        <input
          type="text"
          placeholder="Título do produto"
          value={titulo}
          onChange={(e) => setTitulo(e.target.value)}
          required
          className="p-2 border rounded"
        />
        <select
          placeholder="Categoria"
          value={categoria}
          onChange={(e) => setCategoria(e.target.value)}
          className="p-2 border rounded"
        >
          <option value="">Selecione uma categoria</option>
          <option value="eletronicos">Eletrônicos</option>
          <option value="vestuario">Vestuário</option>
          <option value="livros">Livros</option>
          <option value="materiais">Materiais</option>
        </select>
<select 
placdeholder="ESTADO">


</select>


        <textarea
          placeholder="Descrição"
          value={descricao}
          onChange={(e) => setDescricao(e.target.value)}
          className="p-2 border rounded"
        />
        <input
          type="number"
          placeholder="Preço"
          value={preco}
          onChange={(e) => setPreco(e.target.value)}
          required
          className="p-2 border rounded"
        />
        <button type="submit" className="bg-green-500 text-white py-2 rounded hover:bg-green-600">
          Cadastrar novo produto
        </button>
      </form>

      <h3 className="text-xl font-semibold mb-4">Produtos disponíveis</h3>
      <ul className="space-y-2">
        {produtos.map((p) => (
          <li key={p.id} className="border p-4 rounded">
            <strong>{p.titulo}</strong> - R$ {p.preco}
            <p>{p.descricao}</p>
            <small>Vendedor: {p.vendedor}</small>
          </li>
        ))}
      </ul>
    </div>
  );
}

export default Vendas;
